.avatar-group {
  display: inline-flex;
  align-items: center;
}
.avatar-group-item {
  display: inline-flex;
  border-radius: var(--radius-full);
  box-shadow: 0 0 0 2px var(--background);
}
.avatar-group-item:not(:first-child) {
  margin-inline-start: calc(var(--space-2) * -1);
}

.avatar-group-overflow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-full);
  background: var(--muted);
  color: var(--muted-foreground);
  font-weight: var(--font-weight-semibold);
  font-variant-numeric: tabular-nums;
}
.avatar-group-overflow[data-size='sm'] { inline-size: var(--avatar-sm); block-size: var(--avatar-sm); font-size: var(--font-xs); }
.avatar-group-overflow[data-size='md'] { inline-size: var(--avatar-md); block-size: var(--avatar-md); font-size: var(--font-sm); }
.avatar-group-overflow[data-size='lg'] { inline-size: var(--avatar-lg); block-size: var(--avatar-lg); font-size: var(--font-base); }

/* `.sr-only` for the "+N more" text comes from styles/utilities.css. */

import './AvatarGroup.css'
import { cn } from '../lib/cn'
import { Avatar } from '../Avatar'

type Size = 'sm' | 'md' | 'lg'

export type AvatarGroupItem = { name: string; src?: string }

type Props = {
  items: AvatarGroupItem[]
  /** Show at most this many, then a "+N" overflow disc. Default 4. */
  max?: number
  size?: Size
  className?: string
}

/* Overlapping stack of avatars with a "+N" overflow — a team, the people on a
 * thread. Presentational; the caller supplies the list. The overflow disc
 * carries the hidden count so it is not silent to a screen reader. */
export function AvatarGroup({ items, max = 4, size = 'md', className }: Props) {
  const shown = items.slice(0, max)
  const overflow = items.length - shown.length
  return (
    <div className={cn('avatar-group', className)} data-size={size}>
      {shown.map((item) => (
        <span className="avatar-group-item" key={item.name}>
          <Avatar name={item.name} src={item.src} size={size} />
        </span>
      ))}
      {overflow > 0 && (
        <span className="avatar-group-item avatar-group-overflow" data-size={size}>
          +{overflow}
          <span className="sr-only">{overflow} more</span>
        </span>
      )}
    </div>
  )
}
